from pathlib import Path
import json,sys
ROOT=Path(__file__).resolve().parents[1]
def check(ok,label):
    if not ok:
        print('FAIL - '+label);sys.exit(1)
    print('PASS - '+label)
main=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
php=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
reg=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
js=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.32.0.js').read_text()
notebook=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-research-notebook-v1.js').read_text()
field_helper=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-field-diagnostics-v1.js').read_text()
css=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/css/workspace-v0.32.0.css').read_text()
manifest=json.loads((ROOT/'release-manifest-v0.32.0.json').read_text())
record=json.loads((ROOT/'registry/workspace-product-record-v0.32.0.json').read_text())
check('Version: 0.32.0' in main and "define('SC_WORKSPACE_VERSION', '0.32.0')" in main,'plugin/runtime version')
check(manifest['version']=='0.32.0' and manifest['previous_version']=='0.31.0','manifest release lineage')
check(manifest['release_name']=='Research Notebook Foundation','release name')
check(manifest['storage_schema_version']==28 and manifest['project_schema']=='sc-workspace-project/13.0','storage 28 / project 13.0')
check(manifest['schema_migration_required'] and manifest['migration']['storage_from']==27 and manifest['migration']['storage_to']==28,'storage 27→28 migration')
check(not manifest['migration']['project_schema_unchanged'] and manifest['migration']['project_schema_from']=='sc-workspace-project/12.0' and manifest['migration']['project_schema_to']=='sc-workspace-project/13.0','project schema 12.0→13.0')
check("const STORAGE_VERSION = 28" in js and "const PROJECT_SCHEMA = 'sc-workspace-project/13.0'" in js and 'function migrateV27(raw)' in js,'browser migration runtime')
check(manifest['notebook_workspace_schema']=='sc-workspace-notebook-workspace/1.0' and manifest['notebook_schema']=='sc-workspace-notebook/1.0' and manifest['notebook_block_schema']=='sc-workspace-notebook-block/1.0','Research Notebook schemas')
check(manifest['notebook_export_schema']=='sc-workspace-notebook-export/1.0' and 'exportNotebook' in notebook,'portable notebook export')
check(manifest['research_notebook']['block_types']==['note','source','excerpt','question','claim','reference','checklist','divider','attachment'],'notebook block types')
check(manifest['research_notebook']['limits']=={'notebooks_per_project':30,'sections_per_notebook':40,'blocks_per_notebook':300,'blocks_per_project':600},'notebook local limits')
check("'/notebook-contract'" in php and 'public function notebook_contract()' in php and '/wp-json/sc-workspace/v1/notebook-contract' in manifest['rest_routes'],'Research Notebook REST contract')
check('data-scw-workspace-view="notebook"' in php and 'data-scw-workspace-section="notebook"' in php and 'data-scw-notebook-block-form' in php,'Research Notebook application surface')
check('data-scw-object-to-notebook' in php and 'Add to Notebook' in php and 'promoteNotebookBlock' in js,'capture and explicit promotion UI')
check(manifest['research_notebook']['promotion_explicit'] and manifest['research_notebook']['promotion_preserves_original_block'] and not manifest['research_notebook']['automatic_promotion'],'explicit promotion boundary')
check(not manifest['research_notebook']['automatic_ai'] and not manifest['research_notebook']['ai_required'] and not manifest['governance']['notebook_automatic_ai'],'Notebook does not require or auto-run AI')
check(manifest['research_notebook']['account_backup_inherits_project_boundary'] and manifest['research_notebook']['cross_device_sync_inherits_project_boundary'] and manifest['research_notebook']['restore_points_include_notebooks'],'Notebook inherits project persistence/recovery boundary')
check(manifest['migration']['preserves_account_persistence'] and manifest['migration']['preserves_cross_device_sync'] and manifest['migration']['preserves_version_history'] and manifest['migration']['preserves_project_lifecycle'],'migration preserves current governance state')
check(manifest['canonical_library_path']=='/knowledge-libraries/' and '/knowledge-libraries/' in php,'canonical Knowledge Library route')
check(record['public_version']=='0.32.0' and record['previous_version']=='0.31.0','registry record lineage')
check("BACKUP_KEY = 'sc_workspace_registry_backup_v0320'" in reg and "PENDING_KEY = 'sc_workspace_registry_pending_v0320'" in reg and 'LEGACY_PENDING_KEY_V0310' in reg,'registry pending/backup lineage')
check((ROOT/'history/release-manifest-v0.31.0.json').exists() and (ROOT/'history/workspace-product-record-v0.31.0.json').exists(),'v0.31.0 history preserved')
check(not manifest['field_diagnostics']['automatic_telemetry'] and not manifest['field_diagnostics']['automatic_submission'] and 'userReviewedBeforeExport' in field_helper,'v0.31 field diagnostics retained')
check(':focus-visible' in css and 'prefers-reduced-motion:reduce' in css and 'forced-colors:active' in css,'accessibility hardening retained')
for f in ('sc-workspace-notebook-block-v1.schema.json','sc-workspace-notebook-v1.schema.json','sc-workspace-notebook-workspace-v1.schema.json','sc-workspace-project-v13.schema.json'):
    json.loads((ROOT/'schemas'/f).read_text())
check(True,'Research Notebook schema JSON')
print('VALIDATION PASSED: Sustainable Catalyst Workspace v0.32.0 — Research Notebook Foundation')
